package app.cryptoresearch.mobile;
import android.content.Context;import android.view.View;import android.widget.*;import android.graphics.*;import org.json.*;import java.util.*;
/** Native, read-only analysis of our paper report. Unknown metrics stay unavailable. */
public final class ResearchAnalyticsView extends LinearLayout {
 final int ink=Color.rgb(27,34,48),blue=Color.rgb(56,128,245),muted=Color.rgb(112,122,141);final ArrayList<Double> points=new ArrayList<>();final ArrayList<Integer> drawIndices=new ArrayList<>();
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}TextView line(String s,int size,int color){TextView t=new TextView(getContext());t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(5),0,dp(5));addView(t);return t;}
 String number(JSONObject j,String key,boolean percent){double x=j.optDouble(key,Double.NaN);return !Double.isFinite(x)?"—":String.format(Locale.KOREA,percent?"%.2f%%":"%,.4f",x*(key.equals("win_rate")?100:1));}
 public ResearchAnalyticsView(Context c,byte[] raw){super(c);setOrientation(LinearLayout.VERTICAL);try{JSONObject j=new JSONObject(new String(raw,java.nio.charset.StandardCharsets.UTF_8));line("성과 리포트 · 모의 결과",20,ink);line("승률 "+number(j,"win_rate",true)+"  · 손익비 "+number(j,"profit_factor_net",false)+"\n누적 수수료 "+number(j,"total_fees",false)+" · "+(j.optString("price_currency").equals("KRW")?"KRW":"입력 가격 통화"),13,muted);line("거래 없음/손실 표본 없음은 비율을 — 로 표시합니다.",11,muted);JSONArray curve=j.optJSONArray("equity_curve");if(curve!=null)for(int i=0;i<curve.length();i++){double v=curve.getJSONObject(i).optDouble("equity",Double.NaN);if(Double.isFinite(v))points.add(v);}int step=Math.max(1,(points.size()+299)/300);TreeSet<Integer> selected=new TreeSet<>();if(!points.isEmpty()){selected.add(0);selected.add(points.size()-1);}for(int start=0;start<points.size();start+=step){int lo=start,hi=start;for(int k=start;k<Math.min(points.size(),start+step);k++){if(points.get(k)<points.get(lo))lo=k;if(points.get(k)>points.get(hi))hi=k;}selected.add(lo);selected.add(hi);}drawIndices.addAll(selected);line("손익 곡선 · 봉 순서",14,ink);addView(new Curve(c),new LayoutParams(LayoutParams.MATCH_PARENT,dp(160)));line(points.size()+"개 봉 · "+(j.optBoolean("curve_truncated")?"최근 구간만 표시":"전체 입력 구간")+"\n최종 모의 청산 비용 반영 · 지표는 전체 봉 기준\n극값 보존 샘플링 · 실제 체결 검증 아님",11,muted);JSONArray fills=j.optJSONArray("fill_records");line("최근 체결 내역",16,ink);if(fills==null||fills.length()==0)line("모의 체결이 없어요",13,muted);else for(int i=fills.length()-1;i>=Math.max(0,fills.length()-100);i--){JSONObject f=fills.getJSONObject(i);String ts=java.time.Instant.ofEpochMilli(f.getLong("timestamp_ms")).toString();line(f.getString("side")+" · "+ts+"\n가격 "+number(f,"price",false)+" · 수량 "+String.format(Locale.US,"%.8f",f.getDouble("quantity"))+"\n수수료 "+number(f,"fee",false),12,ink);}line("체결 시각은 엔진의 입력 봉/관측 시각 기준입니다. 최대 최근100건을 표시합니다.",11,muted);}catch(Exception e){line("상세 리포트를 열 수 없어요",13,muted);}}
 final class Curve extends View {final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);final Path path=new Path();Curve(Context c){super(c);setContentDescription("모의 자산 손익 곡선");}protected void onDraw(Canvas canvas){super.onDraw(canvas);p.setColor(muted);p.setTextSize(dp(11));p.setStyle(Paint.Style.FILL);if(points.size()<2){canvas.drawText("곡선을 표시할 봉이 부족합니다",dp(4),getHeight()/2f,p);return;}double min=Collections.min(points),max=Collections.max(points),span=Math.max(max-min,Math.max(1,Math.abs(max)*.00001));canvas.drawText(String.format(Locale.US,"%.2f",max),dp(4),dp(14),p);canvas.drawText(String.format(Locale.US,"%.2f",min),dp(4),getHeight()-dp(3),p);path.reset();int n=points.size();for(int i:drawIndices){float x=dp(4)+(getWidth()-dp(8))*i/(float)(n-1),y=dp(23)+(float)((max-points.get(i))/span)*(getHeight()-dp(46));if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}float last=(float)((max-points.get(n-1))/span)*(getHeight()-dp(46))+dp(23);path.lineTo(getWidth()-dp(4),last);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(2));p.setColor(blue);canvas.drawPath(path,p);}}
}
